function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(key)||'null');return v??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
function cleanCart(raw){const result={};if(!raw||typeof raw!=='object')return result;for(const [id,qty] of Object.entries(raw)){const p=byId(id);if(p&&p.stock!=='out'&&Number.isSafeInteger(qty)&&qty>=1&&qty<=99)result[id]=qty}return result}
function cleanVehicle(raw){return raw&&models[raw.make]?.includes(raw.model)?{make:raw.make,model:raw.model,year:raw.year||'',engine:raw.engine||'',customerId:raw.customerId||''}:null}
